/** At phone width amounts stay inline, badges move under the description and metadata hides. */
export const Phone: Story = {
  args: Money.args,
  globals: { viewport: { value: 'rowListPhone' } },
  parameters: {
    chromatic: {
      viewports: [375],
    },
